// The verifier's suite. Two things are pinned here rather than assumed:
// the fixture (generated by the owning script in the main repository's
// `scripts/sign-web-dist.test.ts` pass) proves the two implementations agree on
// one format, and the shape test proves the pinned production key is a well-formed
// Ed25519 key. The production key's *pairing* cannot be tested here — its private
// half lives only in the platform repository's Actions secret, and the release
// job's self-verify step is what proves that pairing on every release.

import { describe, expect, it } from "bun:test";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { decodeKeyBlock, verifyWebDist, readPublicKey } from "./web-sig.ts";

// Fixture pair — a THROWAWAY key generated by `sign-web-dist.ts --generate` (not the
// production key, which has no local private half to sign with). Signed message and
// signature were generated by the owning script.
const FIXTURE_MESSAGE = Buffer.from("a fixture message generated to prove the two implementations agree on one format");
const FIXTURE_PUB = "1S2zTNpqoDA81Gp8Hq+s+vdoFMz7DwKQ3LBxxq3GjCM=";
const FIXTURE_SIG = "S5qdGvnJX6hRTJhpCC3l8HDGa5gAe9rov48urkV8IA675jJmy5T96nflYqC3p2ZmN0jl+hA2HKi3mhrjdCLYBw==";

const PUB = join(import.meta.dir, "web-dist-signing.pub");

describe("web-sig", () => {
	it("accepts the fixtures the owning script generated", () => {
		const fixturePub = `untrusted comment: anthers web-dist Ed25519 signing key\n${FIXTURE_PUB}\n`;
		const fixtureSig = `untrusted comment: anthers web-dist Ed25519 signature\n${FIXTURE_SIG}\n`;
		expect(verifyWebDist(FIXTURE_MESSAGE, fixtureSig, fixturePub)).toBe(true);
	});

	it("refuses bytes that changed after signing", () => {
		const fixturePub = `untrusted comment: anthers web-dist Ed25519 signing key\n${FIXTURE_PUB}\n`;
		const fixtureSig = `untrusted comment: anthers web-dist Ed25519 signature\n${FIXTURE_SIG}\n`;
		expect(verifyWebDist(Buffer.concat([FIXTURE_MESSAGE, Buffer.from("x")]), fixtureSig, fixturePub)).toBe(false);
	});

	it("refuses the fixture signature against the production key", () => {
		expect(verifyWebDist(FIXTURE_MESSAGE, `untrusted comment: anthers web-dist Ed25519 signature\n${FIXTURE_SIG}\n`, readFileSync(PUB, "utf8"))).toBe(false);
	});

	it("rejects a signature of the wrong size outright", () => {
		const shortSig = `untrusted comment: anthers web-dist Ed25519 signature\n${Buffer.alloc(32).toString("base64")}\n`;
		expect(() => decodeKeyBlock(shortSig, 64, "signature")).toThrow(/expected 64 bytes/);
	});

	it("the pinned production key parses as a 32-byte Ed25519 public key", () => {
		const key = readPublicKey(readFileSync(PUB, "utf8"));
		expect(key.asymmetricKeyType).toBe("ed25519");
	});
});